"""Deterministic, offline lookup over a retained full-source SEC corpus."""

from __future__ import annotations

import hashlib
import json
import re

from tradingagents.dataflows.vendors.sec_documents import DisclosurePackage

MAX_PASSAGES = 3
MAX_CHARS = 12_000
MAX_QUERY_CHARS = 200
_WORD = re.compile(r"[a-z0-9]+")
_STOP = {"a", "an", "and", "for", "in", "of", "the", "to", "what", "which"}
_ALIASES = {
    "rpo": "remaining performance obligations",
    "backlog": "remaining performance obligations",
}
_NAMED_NOTES = re.compile(r"\b(20\d{2})\s+convertible\s+notes\b")
_COORDINATED_NOTES = re.compile(r"\b(20\d{2})\s+and\s+(20\d{2})\s+convertible\s+notes\b")


def corpus_hash(corpus: DisclosurePackage) -> str:
    """Hash the exact retained package, including source hashes and block text."""
    data = json.dumps(corpus.model_dump(mode="json"), sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(data.encode()).hexdigest()


def _terms(query: str) -> tuple[str, list[str]]:
    normalized = " ".join(_WORD.findall(query.lower()))
    for short, expanded in _ALIASES.items():
        normalized = re.sub(r"\b" + short + r"\b", expanded, normalized)
    words = [word for word in normalized.split() if word not in _STOP]
    return normalized, words


def _contains(text: str, term: str) -> bool:
    suffix = "s?" if len(term) >= 4 and not term.endswith("s") else ""
    return re.search(r"\b" + re.escape(term) + suffix + r"\b", text) is not None


def _note_years(text: str) -> set[str]:
    """Recognize an explicit year attached to Convertible Notes, not a date nearby."""
    lowered = text.lower()
    years = set(_NAMED_NOTES.findall(lowered))
    for first, second in _COORDINATED_NOTES.findall(lowered):
        years.update((first, second))
    return years


def search_filing_evidence(
    corpus: DisclosurePackage, query: str, *, max_passages: int = MAX_PASSAGES,
    max_chars: int = MAX_CHARS,
) -> dict:
    """Return whole source blocks, never a shortened table or a new network fetch.

    Callers retain this response alongside the corpus. Returned text is unvalidated
    source material; claims still require the disclosure evidence validator.
    """
    if not 1 <= max_passages <= MAX_PASSAGES or not 1 <= max_chars <= MAX_CHARS:
        raise ValueError(f"Search limit exceeded: at most {MAX_PASSAGES} passages and {MAX_CHARS} characters")
    if not isinstance(query, str) or not query.strip() or len(query) > MAX_QUERY_CHARS:
        raise ValueError(f"Search query must contain 1-{MAX_QUERY_CHARS} characters")
    phrase, terms = _terms(query)
    if not terms:
        raise ValueError("Search query has no searchable terms")
    requested_notes = _note_years(query)
    section_window = {}
    if len(terms) <= 2:
        ordered = sorted(
            corpus.documents,
            key=lambda doc: (doc.filing.filed_date, doc.filing.accession), reverse=True,
        )
        for document in ordered:
            filing = document.filing
            if filing.cik != corpus.cik or filing.filed_date > corpus.as_of or (
                filing.report_date and filing.report_date > corpus.as_of
            ):
                continue
            for index, block in enumerate(document.blocks):
                heading = block.text.strip()
                if (
                    len(heading) > 120 or "|" in heading
                    or not (re.match(r"^(?:Note|Item) \d+[. ]", heading) or heading.istitle())
                    or not all(_contains(heading.lower(), term) for term in terms)
                ):
                    continue
                for offset, nearby in enumerate(document.blocks[index:index + max_passages]):
                    if offset and (
                        re.match(r"^(?:Note|Item) \d+[. ]", nearby.text)
                        or nearby.text.istitle()
                    ):
                        break
                    section_window[(document.source_id, nearby.locator)] = 100 - offset * 10
                break
            if section_window:
                break
    candidates = []
    gaps = list(corpus.gaps)
    eligible_notes = set()
    incomplete_notes = set()
    for document in corpus.documents:
        filing = document.filing
        if filing.cik != corpus.cik or filing.filed_date > corpus.as_of or (
            filing.report_date is not None and filing.report_date > corpus.as_of
        ):
            gaps.append(f"{filing.accession}: excluded by issuer or analysis cutoff")
            continue
        if document.source_id != "sec-document-" + hashlib.sha256(document.url.encode()).hexdigest():
            gaps.append(f"{filing.accession}: source identity mismatch")
            continue
        for block in document.blocks:
            block_notes = _note_years(block.section + " " + block.text) & requested_notes
            if block.truncated:
                gaps.append(f"{filing.accession} {block.locator}: incomplete source block omitted")
                incomplete_notes.update(block_notes)
                continue
            if requested_notes and not block_notes:
                continue
            eligible_notes.update(block_notes)
            heading = block.section.lower()
            body = block.text.lower()
            heading_hits = sum(_contains(heading, term) for term in terms)
            body_hits = sum(_contains(body, term) for term in terms)
            if not heading_hits and not body_hits and (document.source_id, block.locator) not in section_window:
                continue
            score = (
                section_window.get((document.source_id, block.locator), 0)
                + 8 * (phrase in heading) + 10 * (phrase in body)
                + 2 * heading_hits + body_hits + 4 * (body_hits == len(terms))
            )
            candidates.append((score, document, block, block_notes))
    candidates.sort(key=lambda item: (
        -item[1].filing.filed_date.toordinal(), -item[0],
        item[1].filing.accession, item[2].locator,
    ) if requested_notes else (
        -item[0], -item[1].filing.filed_date.toordinal(),
        item[1].filing.accession, item[2].locator,
    ))
    passages = []
    used = 0
    returned_notes = set()
    oversized_notes = set()
    # Reserve one ranked passage per requested instrument before filling spare slots.
    if len(requested_notes) > 1:
        chosen = []
        for year in sorted(requested_notes):
            match = next((item for item in candidates if year in item[3] and item not in chosen), None)
            if match is not None:
                chosen.append(match)
        candidates = chosen + [item for item in candidates if item not in chosen]
    for _, document, block, block_notes in candidates:
        if len(passages) >= max_passages:
            break
        if len(block.text) > max_chars - used:
            gaps.append(
                f"{document.filing.accession} {block.locator}: passage omitted by search size limit"
            )
            oversized_notes.update(block_notes)
            continue
        filing = document.filing
        passages.append({
            "source_id": document.source_id,
            "locator": block.locator,
            "section": block.section,
            "text": block.text,
            "truncated": False,
            "currency": block.currency,
            "currency_locator": block.currency_locator,
            "filing_form": filing.form,
            "filing_date": filing.filed_date.isoformat(),
            "filing_accession": filing.accession,
            "url": document.url,
            "content_hash": document.content_hash,
            "passage_hash": hashlib.sha256(block.text.encode()).hexdigest(),
        })
        used += len(block.text)
        returned_notes.update(block_notes)
    for year in sorted(requested_notes):
        if year in returned_notes:
            continue
        if year in oversized_notes:
            gaps.append(f"{year} Convertible Notes: passage omitted by search size limit")
        elif year in eligible_notes:
            gaps.append(f"{year} Convertible Notes: omitted by search passage limit")
        elif year in incomplete_notes:
            gaps.append(f"{year} Convertible Notes: incomplete source block omitted")
        else:
            gaps.append(f"no passage names the {year} Convertible Notes")
    if not passages and not requested_notes:
        gaps.append("not found in retained filings")
    return {
        "query": query,
        "corpus_hash": corpus_hash(corpus),
        "passages": passages,
        "gaps": list(dict.fromkeys(gaps)),
    }

def _validate_search_trace(trace, corpus):
    if not isinstance(trace, dict):
        raise ValueError("Malformed document search trace")
    counts = dict.fromkeys(_ROLES, 0)
    for key, entry in trace.items():
        if (not isinstance(entry, dict) or entry.get("role") not in _ROLES
                or not isinstance(entry.get("call_id"), str) or not entry["call_id"]
                or key != f"{entry['role']}:{entry['call_id']}"
                or type(entry.get("counted")) is not bool):
            raise ValueError("Malformed document search journal entry")
        status = entry.get("status")
        if status not in {"ok", "not_found", "invalid_query", "unavailable", "limit_reached"}:
            raise ValueError("Malformed document search journal status")
        if entry["counted"] != (status != "limit_reached"):
            raise ValueError("Invalid document search counted status")
        counts[entry["role"]] += entry["counted"]
        if counts[entry["role"]] > _LIMIT:
            raise ValueError("Retained document search call limit exceeded")
        passages = entry.get("passages")
        if (not isinstance(passages, list) or len(passages) > 3
                or any(not isinstance(p, dict) or not isinstance(p.get("text"), str) for p in passages)
                or sum(len(p["text"]) for p in passages) > 12000):
            raise ValueError("Document search passage limit exceeded")
        if bool(passages) != (status == "ok"):
            raise ValueError("Document search passage status mismatch")
        if passages and corpus is None:
            raise ValueError("Document passages exist without retained corpus")
        if entry.get("corpus_hash") != (corpus_hash(corpus) if corpus else None):
            raise ValueError("Document search journal corpus mismatch")

def retained_search_packages(state) -> list[DisclosurePackage]:
    """Reconstruct quoteable packages solely from exact journal-returned blocks."""
    corpus = validated_document_corpus(state)
    trace = state.get("document_search_trace") or {}
    _validate_search_trace(trace, corpus)
    if corpus is None:
        if any(not isinstance(entry, dict) or entry.get("passages") for entry in trace.values()):
            raise ValueError("Document passages exist without retained corpus")
        return []
    documents = {doc.source_id: doc for doc in corpus.documents}
    packages = []
    for key, entry in trace.items():
        if isinstance(entry.get("query"), str) and entry["query"].casefold().startswith("transcript:"):
            from tradingagents.agents.transcript_access import validated_transcript_record

            validated_transcript_record(state)
            if entry.get("transcript_hash") != (state.get("transcript_sources") or {}).get("record_hash"):
                raise ValueError("Retained transcript search source changed")
        if not isinstance(entry, dict) or key != f"{entry.get('role')}:{entry.get('call_id')}" or entry.get("role") not in _ROLES:
            raise ValueError("Malformed document search journal entry")
        if entry.get("corpus_hash") != corpus_hash(corpus):
            raise ValueError("Document search journal corpus mismatch")
        passages = entry.get("passages")
        if not isinstance(passages, list) or len(passages) > 3 or sum(len(p.get("text", "")) for p in passages) > 12000:
            raise ValueError("Document search passage limit exceeded")
        if not passages:
            continue
        if not entry.get("counted") or entry.get("status") != "ok":
            raise ValueError("Uncounted document search passage")
        try:
            expected = search_retained_document_sources(state, entry["query"], max_passages=3, max_chars=12000)
        except (KeyError, ValueError) as exc:
            raise ValueError("Invalid retained document search query") from exc
        if expected["passages"] != passages:
            raise ValueError("Document search passage differs from retained source")
        chosen = {}
        for passage in passages:
            if passage.get("provider") == "Alpha Vantage":
                continue  # Exact vendor return validated above; never accepted filing evidence.
            doc = documents.get(passage["source_id"])
            if doc is None or passage["content_hash"] != doc.content_hash:
                raise ValueError("Document search source mismatch")
            block = next((b for b in doc.blocks if b.locator == passage["locator"]), None)
            if block is None or block.truncated or passage["passage_hash"] != hashlib.sha256(block.text.encode()).hexdigest():
                raise ValueError("Document search block mismatch")
            chosen.setdefault(doc.source_id, set()).add(block.locator)
        if not chosen:
            continue
        selected = tuple(
            doc.model_copy(update={"blocks": tuple(
                block for block in doc.blocks if block.locator in chosen.get(doc.source_id, ())
            )})
            for doc in corpus.documents if doc.source_id in chosen
        )
        packages.append(corpus.model_copy(update={
            "documents": selected,
            "selected_accessions": tuple(dict.fromkeys(doc.filing.accession for doc in selected)),
        }))
    return packages

def _check_retained(record: dict, scope: dict, records: dict, corpus, state) -> None:
    if (
        not isinstance(record, dict) or record.get("schema_version") != 1
        or record.get("scope") != scope or record.get("question_records") != records
        or record.get("query_set_hash") != _digest(records)
        or record.get("corpus_hash") != (corpus_hash(corpus) if corpus else None)
        or record.get("transcript_hash") != (state.get("transcript_sources") or {}).get("record_hash")
    ):
        raise ValueError("Document follow-up scope, questions or corpus mismatch")
    seal = {key: value for key, value in record.items() if key != "record_hash"}
    if record.get("record_hash") != _digest(seal):
        raise ValueError("Document follow-up record hash mismatch")
    expected_questions = [
        (role, question) for role in _ROLES
        for question in records[role]["questions"]
    ]
    results = record.get("results")
    if not isinstance(results, list) or len(results) != len(expected_questions):
        raise ValueError("Document follow-up result count mismatch")
    sources = {document.source_id: document for document in corpus.documents} if corpus else {}
    for result, (role, question) in zip(results, expected_questions, strict=True):
        if not isinstance(result, dict) or any(
            result.get(field) != value for field, value in (
                ("role", role), ("question_id", question["question_id"]),
                ("query", question["query"]),
            )
        ):
            raise ValueError("Document follow-up question mismatch")
        passages = result.get("passages")
        if (
            not isinstance(passages, list) or len(passages) > _MAX_PASSAGES
            or sum(len(p.get("text", "")) for p in passages if isinstance(p, dict)) > _MAX_CHARS
        ):
            raise ValueError("Document follow-up passage limit exceeded")
        if result.get("status") == "found" and not passages:
            raise ValueError("Document follow-up found status has no passage")
        if result.get("status") != "found" and passages:
            raise ValueError("Document follow-up passage status mismatch")
        if result.get("status") not in {"found", "not_found", "unavailable", "invalid_query"}:
            raise ValueError("Invalid document follow-up status")
        if question["query"].casefold().startswith("transcript:") and passages:
            expected = search_retained_document_sources(state, question["query"],
                                                       max_passages=_MAX_PASSAGES, max_chars=_MAX_CHARS)
            if expected["passages"] != passages:
                raise ValueError("Document follow-up transcript differs from retained source")
            continue
        for passage in passages:
            if not isinstance(passage, dict):
                raise ValueError("Malformed document follow-up passage")
            document = sources.get(passage.get("source_id"))
            block = next(
                (b for b in document.blocks if b.locator == passage.get("locator")),
                None,
            ) if document else None
            if document is None or block is None or block.truncated:
                raise ValueError("Document follow-up passage source missing")
            filing = document.filing
            expected = {
                "source_id": document.source_id,
                "locator": block.locator,
                "section": block.section,
                "text": block.text,
                "truncated": False,
                "currency": block.currency,
                "currency_locator": block.currency_locator,
                "filing_form": filing.form,
                "filing_date": filing.filed_date.isoformat(),
                "filing_accession": filing.accession,
                "url": document.url,
                "content_hash": document.content_hash,
                "passage_hash": hashlib.sha256(block.text.encode()).hexdigest(),
                "citation_ref": f"{document.source_id}#{block.locator}",
            }
            if passage != expected:
                raise ValueError("Document follow-up passage differs from retained source")
